dat_full |&gt;
  select(matches("attention")) |&gt;
  imap(~ tibble(var = str_extract(.y, "([a-zA-Z-]+)_attention", group = 1),
                p = table(.x) |&gt; prop.table() |&gt; as_tibble()) |&gt;
         unnest(cols = p)) |&gt;
  list_rbind() |&gt;
  rename(`Check` = `.x`,
         p = n) |&gt;
  gt(rowname_col = "var") |&gt;
  fmt_percent(columns = p,
